select is((select count(*) from public.node_updates where node_id = '40000000-0000-0000-0000-000000000001' and kind = 'status_change' and body = 'Found a mistake' and from_status = 'verified' and to_status = 'in_progress'), 1::bigint, 'T7: audit row written with the comment');
