select throws_ok($$ select public.transition_task_status('40000000-0000-0000-0000-000000000001', 'todo', 'in_progress', null) $$, 'P0001', 'E_NOT_AUTHORIZED', 'unauthenticated call rejected');
reset role;
select is((select has_function_privilege('anon', 'public.transition_task_status(uuid,public.task_status,public.task_status,text)', 'execute')), false, 'anon cannot execute transition_task_status');
select * from finish();
rollback;